{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C10", "C14", "C33", "C139", "C126", "C84", "C205", "C193", "C201", "C183", "C191"],
  "contradictory_card_ids": ["C225", "C209", "C198", "C220", "C262", "C248", "C263", "C253", "C232", "C242", "C273", "C274", "C230", "C252", "C237", "C233"],
  "prediction_basis_card_ids": ["C10", "C14", "C33", "C139", "C126", "C84", "C205"],
  "claims": [
    {
      "claim": "The most transferable gold contexts support F >= 20%: nilotinib has an assumed fasted absolute F of 31% (C10), and GSK1322322 has measured absolute F of 57% fasted and 77% fed (C33, C14).",
      "card_ids": ["C10", "C14", "C33"]
    },
    {
      "claim": "L4/L5 permeability evidence indicates the anilinopyrimidine TKI chemotype can be well absorbed: nilotinib Caco-2-derived human effective permeability ~1.5e-4 cm/s (C139) and high-permeability/low-efflux analogs (C205, C193, C201, C183, C191).",
      "card_ids": ["C139", "C205", "C193", "C201", "C183", "C191"]
    },
    {
      "claim": "L3 alflutinib, a close structural analog, shows measurable oral exposure after 80 mg (C126) and only a 1.23-fold Cmax increase with itraconazole (C84), suggesting meaningful absorption and a modest CYP3A contribution.",
      "card_ids": ["C126", "C84"]
    },
    {
      "claim": "L6 hepatic clearance records for related acrylamide TKIs show moderate-to-high HLM intrinsic clearance (osimertinib 64.2, neratinib 39-42, rociletinib 20.15, poziotinib 22; C262, C232, C242, C263, C248) and imatinib is CYP-metabolized with HLM t1/2 60 min (C252, C237, C233); this is a mechanistic first-pass concern but does not quantify F or establish F < 20%.",
      "card_ids": ["C262", "C232", "C242", "C263", "C248", "C252", "C237", "C233"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C262", "C248", "C263", "C253", "C232", "C242", "C273", "C274", "C230", "C252", "C237", "C233"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific or alflutinib-specific hepatic clearance/metabolic stability measurement; L6 records are for other acrylamide TKIs and imatinib.",
    "L3 alflutinib exposure lacks an IV comparator, so absolute F cannot be derived from it.",
    "Nilotinib F of 31% is an assumed value, and its transfer to the query is uncertain because of structural differences.",
    "The query's low neutral fraction and possible efflux/first-pass metabolism could reduce F, but no quantitative F impact is available.",
    "Food, dose, formulation, and species differences between the query and the gold contexts are unmeasured."
  ],
  "decision_summary": "Predicted high (F >= 20%) is retained. The most transferable gold contexts (nilotinib 31% fasted; GSK1322322 57-77%) and L3 oral exposure for the close alflutinib analog support meaningful absorption; L4/L5 permeability records indicate the anilinopyrimidine TKI chemotype can be well absorbed. L6 hepatic clearance records for related acrylamide TKIs add mechanistic concern about first-pass metabolism but are indirect and do not establish F < 20%; confidence is weakened to low."
}

